  set readOnly(bool ro) {
    if (_readOnly == ro) return;
    _readOnly = ro;
    
    // Close text input connection when readonly
    if (_readOnly && _controller.connection != null) {
      _controller.connection?.close();
      _controller.connection = null;
    }
    
    markNeedsPaint();
