      _gutterWidth = _gutterStyle.gutterWidth ?? 
        ((_lines.length.toString().length) * _tempTp.width) + _gutterPadding * 2;
      
      _lineTpCache.clear();
      _cachedSpans.clear();
      
      markNeedsLayout();
